package dev.thillainirmal.shopops.order;
import dev.thillainirmal.shopops.catalog.*; import org.junit.jupiter.api.Test; import java.math.BigDecimal; import java.time.*; import java.util.*; import static org.assertj.core.api.Assertions.*; import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.*;
class OrderServiceTest {
 @Test void atomicallyReservesStockAndComputesAuthoritativeTotal(){var products=mock(ProductRepository.class);var orders=mock(CustomerOrderRepository.class);var product=new Product(UUID.randomUUID(),"TRAIL-45","Pack","desc","outdoor",new BigDecimal("8999.00"),5);when(products.findBySkuIgnoreCase("TRAIL-45")).thenReturn(Optional.of(product));when(orders.save(any())).thenAnswer(i->i.getArgument(0));var service=new OrderService(products,orders,Clock.fixed(Instant.parse("2026-10-30T04:00:00Z"),ZoneOffset.UTC));var order=service.reserve("buyer@example.com","TRAIL-45",2);assertThat(order.getTotal()).isEqualByComparingTo("17998.00");assertThat(product.getStockQuantity()).isEqualTo(3);assertThat(order.getStatus()).isEqualTo("RESERVED");}
 @Test void refusesOverselling(){var products=mock(ProductRepository.class);var orders=mock(CustomerOrderRepository.class);var product=new Product(UUID.randomUUID(),"ONE","Last","desc","test",BigDecimal.TEN,1);when(products.findBySkuIgnoreCase("ONE")).thenReturn(Optional.of(product));var service=new OrderService(products,orders);assertThatThrownBy(()->service.reserve("buyer@example.com","ONE",2)).isInstanceOf(IllegalStateException.class).hasMessageContaining("insufficient stock");verify(orders,never()).save(any());}
}
